import{_ as i,l as n,o as e,c as l,v as t,p as s,x as o,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"策略证明与延迟接受","description":"","frontmatter":{"title":"策略证明与延迟接受","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/matching-strategy-proof.md","filePath":"econ/matching-strategy-proof.md","lastUpdated":1789023840000}'),E={name:"econ/matching-strategy-proof.md"};function A(c,a,m,D,_,B){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="策略证明与延迟接受" tabindex="-1">策略证明与延迟接受 <a class="header-anchor" href="#策略证明与延迟接受" aria-label="Permalink to &quot;策略证明与延迟接受&quot;">​</a></h1><div class="epigraph"><p>延迟接受对求婚方是占优策略诚实的；接收方可以靠谎报偏好把匹配挪向对自己更好的稳定点。</p><footer>—— Dubins and Freedman, Machiavelli and the Gale–Shapley Algorithm, AMM, 1981；Roth, The Economics of Matching: Stability and Incentives, Mathematics of Operations Research, 1982</footer></div><p><a href="/econ/gale-shapley">上一课</a>给出稳定匹配与 DA，并钉了求婚方最优。缺口是偏好为私有时，报名单是不是占优策略。若诚实不是均衡，稳定在纸上、操纵在路上。本课钉单边策略证明与接收方可操纵，不把早期解约、逐级退出写成柠檬，也不把 VCG 的货币转移搬进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>策略证明：每人把真实偏好报给机制是占优策略。DA 对求婚方：无论别人报什么，求婚方按真名单往下求，不会比谎报更好。直觉：对求婚方而言，DA 已经给了他在「所报偏好」下的最优稳定匹配；把名单改差，等于主动丢掉更好的对象，或把阻塞对让给别人。Dubins–Freedman 与 Roth 把这句话写成定理。</p><p>接收方不然。接收方在求婚方最优稳定匹配上最差，谎报可以把某次「暂持」改成拒绝，从而迫使算法走到另一稳定匹配，对自己更好。因此：不存在既稳定、又对双方都策略证明的机制——这是双边匹配的不可能，比后课 Gibbard–Satterthwaite 更早、更窄（对象是匹配，不是任意社会选择）。</p><h3 id="占优策略不是贝叶斯-ic" tabindex="-1">占优策略不是贝叶斯 IC <a class="header-anchor" href="#占优策略不是贝叶斯-ic" aria-label="Permalink to &quot;占优策略不是贝叶斯 IC&quot;">​</a></h3><p>策略证明要求对任意对手报告都最优，不依赖先验。市场设计常用这一层，因为医院、学生很难共有一个估值分布。贝叶斯 IC 更宽，可以让接收方在期望上诚实，但不是 DA 的性质。</p><p><span class="marginnote">农村医院定理（Roth）：所有稳定匹配中，同一医院的填满名额相同，未被匹配的人也相同。接收方操纵改变的是「和谁配」，不是名额总数——对常满的大医院，操纵空间更在对象质量，不在数量。</span></p><p>一对一严格偏好下，求婚方策略证明是干净的。 多对一里，接收方（学校）即使诚实，名额与捆绑也会另造操纵，本课只钉经典 DA。 可操纵不等于均衡里人人操纵：别人诚实、自己谎报才有利时，才构成对诚实的偏离。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限双边、严格偏好、DA（指定求婚边）。先证求婚方：任何对真偏好的偏离，可用「首次吃亏的对象」把阻塞对引回来，证明不更好。再给接收方一个三人教具：诚实走到求婚方最优，接收方把第二名报到第一之前，可以抓住原本到不了手的对象。最后：稳定 + 双方策略证明 \\(\\Rightarrow\\) 矛盾（除非偏好结构退化）。</p>',12)),(e(),s(d,null,{default:o(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DA%5B%22%E5%BB%B6%E8%BF%9F%E6%8E%A5%E5%8F%97%22%5D%20--%3E%20PROP%5B%22%E6%B1%82%E5%A9%9A%E6%96%B9%EF%BC%9A%E8%AF%9A%E5%AE%9E%E5%8D%A0%E4%BC%98%22%5D%0A%20%20DA%20--%3E%20REC%5B%22%E6%8E%A5%E6%94%B6%E6%96%B9%EF%BC%9A%E5%8F%AF%E6%93%8D%E7%BA%B5%22%5D%0A%20%20STAB%5B%22%E8%A6%81%E6%B1%82%E7%A8%B3%E5%AE%9A%22%5D%20--%3E%20IMP%5B%22%E6%97%A0%E6%B3%95%E5%8F%8C%E8%BE%B9%E9%83%BD%E7%AD%96%E7%95%A5%E8%AF%81%E6%98%8E%22%5D%0A%20%20PROP%20--%3E%20SP%5B%22%E5%8D%95%E8%BE%B9%E7%AD%96%E7%95%A5%E8%AF%81%E6%98%8E%E5%8F%AF%E7%94%A8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DA 把求婚方变成「按名单消耗拒绝」：他没有「先藏起真爱、等别人被拒再出手」的好处，因为算法已经让他按顺序试完所有更好的。接收方的暂持是路径依赖的：谎报改变拒绝时点，等于选择格上另一端附近的点。稳定作为约束把机制钉在格上；策略证明要把格的两端同时变成占优策略结果，做不到。</p><p>与拍卖对照：二价对所有人占优策略诚实，因为有货币把外部性收成价格。匹配没有转移，诚实只能送给一边。要把两边都按住，必须放弃稳定，或引入货币（赋值博弈、VCG 式转移），那是后课机制设计，不是本课的 DA。接收方的操纵空间来自格：诚实把他钉在最差稳定点，谎报等于在格上另选一点。不是所有谎报都有利，但存在偏好轮廓使诚实不是最优反应，故不是占优策略。</p><p>稳定作为约束把机制钉在格上；两边同时策略证明会要求格的两端都是占优结果，做不到。 谎报改变的是拒绝时点，从而选择格上另一端附近的点，不是改名额总数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>大规模、近似随机偏好时，一个人的操纵收益可以很小（Immorlica–Mahdian、Kojima–Pathak 一类极限），诚实近似成立。这是极限，不是定理被取消。夫妻捆绑、学院配额、转学契约会破坏求婚方策略证明。早期签约、限期承诺（exploding offer）是另一套「在 DA 之前就匹配」，那是市场崩溃的时序，不是 DA 内部的谎报。</p><p>后课默认：DA 对求婚方策略证明、对接收方可操纵；稳定与双边策略证明不可兼得。信息课序里的柠檬、信号不改这句话。</p><h3 id="选哪一边求婚就是选谁被保护" tabindex="-1">选哪一边求婚就是选谁被保护 <a class="header-anchor" href="#选哪一边求婚就是选谁被保护" aria-label="Permalink to &quot;选哪一边求婚就是选谁被保护&quot;">​</a></h3><p>市场设计选住院医师求婚，则医师诚实、医院可操纵。反过来亦然。政策选的是激励保护哪一边，不是算法是否「公平」。没有货币时，这是仅有的杠杆。</p><p><span class="marginnote">Roth 1982 同时证明：不存在稳定且对双方都策略证明的机制。后课 GS 不可能是任意社会选择的版本；本课只在匹配核上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DA 对求婚方占优策略诚实，对接收方一般不是。</li><li>稳定与双边策略证明不可兼得。</li><li>操纵改的是格上的位置，农村医院定理限制名额变化。</li><li>无转移时，选求婚边即选被保护的一边。</li><li>出处：Dubins and Freedman, <em>AMM</em> 1981；Roth, <em>Math. Oper. Res.</em> 1982。</li></ul>',12))])}const b=i(E,[["render",A]]);export{u as __pageData,b as default};
